styles:
@media (prefers-reduced-motion: reduce) {
  .footer-shapes-module__zX7oxG__track, .footer-shapes-module__zX7oxG__shape { animation: auto ease 0s 1 normal none running none; }
}

@layer components {
  .btn { cursor: pointer; white-space: nowrap; transition-property: color, background-color, border-color, outline-color, text-decoration-color, fill, stroke, --tw-gradient-from, --tw-gradient-via, --tw-gradient-to; transition-timing-function: var(--tw-ease,var(--default-transition-timing-function)); transition-duration: var(--tw-duration,var(--default-transition-duration)); font-family: var(--font-diatype-rounded); --tw-font-weight: var(--font-weight-medium); font-weight: var(--font-weight-medium); --tw-tracking: var(--tracking-wider); letter-spacing: var(--tracking-wider); text-transform: uppercase; color: var(--btn-fg); flex-shrink: 0; justify-content: center; align-items: center; display: inline-flex; position: relative; overflow: hidden; }
  .btn [data-text] { text-box: cap alphabetic; }
  .btn svg { flex-shrink: 0; }
  .btn:disabled { cursor: not-allowed; color: var(--btn-fg); }
  @supports (color:color-mix(in lab, red, red)) {
  .btn:disabled { color: color-mix(in srgb,var(--btn-fg)50%,transparent); }
}
  .btn:disabled { border-color: var(--color-stroke-muted); }
  .btn[aria-busy="true"] { color: rgba(0, 0, 0, 0); cursor: wait; }
  .btn[aria-busy="true"] .btn-spinner { color: var(--btn-fg); }
  .btn-sm { height: calc(var(--spacing)*6); padding-inline: calc(var(--spacing)*2.5); font-family: var(--font-diatype); text-transform: uppercase; letter-spacing: 0.01em; font-size: 0.75rem; font-weight: 400; line-height: 1.1; }
  .btn-sm [data-text] { padding-left: calc(var(--spacing)*.5); padding-right: calc(var(--spacing)*1); }
  .btn-sm [data-text]:only-child { padding-inline: calc(var(--spacing)*.5); }
  .btn-md { height: calc(var(--spacing)*8); padding-inline: calc(var(--spacing)*3); font-family: var(--font-diatype); text-transform: uppercase; letter-spacing: 0.01em; font-size: 0.75rem; font-weight: 400; line-height: 1.1; }
  .btn-md [data-text] { padding-inline: calc(var(--spacing)*1); }
  .btn-lg { height: calc(var(--spacing)*10); padding-inline: calc(var(--spacing)*2.5); font-family: var(--font-diatype); text-transform: uppercase; letter-spacing: 0.01em; font-size: 0.875rem; font-weight: 400; line-height: 1.1; }
  .btn-lg [data-text] { padding-inline: calc(var(--spacing)*1.5); }
  .btn-icon-only { padding: calc(var(--spacing)*0); }
  .btn-sm.btn-icon-only { width: calc(var(--spacing)*6); height: calc(var(--spacing)*6); }
  .btn-md.btn-icon-only { width: calc(var(--spacing)*8); height: calc(var(--spacing)*8); }
  .btn-lg.btn-icon-only { width: calc(var(--spacing)*10); height: calc(var(--spacing)*10); }
  .btn-primary { background-color: var(--color-fill-dark-base); --btn-fg: var(--color-brand-vestre-yellow); }
  .btn-primary:hover, .btn-primary[data-state="hover"] { background-color: var(--color-fill-dark-strong); }
  .dark-surface .btn-primary, [data-theme="dark"] .btn-primary { border-style: var(--tw-border-style); border-width: 1px; border-color: var(--color-stroke-brand-base); background-color: var(--color-transparent); }
  :is(.dark-surface .btn-primary, [data-theme="dark"] .btn-primary):hover, :is(.dark-surface .btn-primary, [data-theme="dark"] .btn-primary)[data-state="hover"] { --btn-fg: var(--color-stroke-brand-strong); border-color: var(--color-stroke-brand-strong); }
  .btn-secondary { border-style: var(--tw-border-style); border-width: 1px; border-color: var(--color-stroke-base); --btn-fg: #333337; }
  .btn-secondary:hover, .btn-secondary[data-state="hover"] { --btn-fg: var(--color-ink-subtle); border-color: var(--color-stroke-subtle); }
  .dark-surface .btn-secondary, [data-theme="dark"] .btn-secondary { border-style: var(--tw-border-style); border-width: 1px; border-color: var(--color-stroke-base); --btn-fg: var(--color-ink-on-dark-base); }
  :is(.dark-surface .btn-secondary, [data-theme="dark"] .btn-secondary):hover, :is(.dark-surface .btn-secondary, [data-theme="dark"] .btn-secondary)[data-state="hover"] { --btn-fg: var(--color-ink-on-dark-base); border-color: var(--color-stroke-on-dark-subtle); }
  .btn-ghost { --btn-fg: #333337; }
  .btn-ghost:hover, .btn-ghost[data-state="hover"] { background-color: var(--color-fill-muted); }
  .dark-surface .btn-ghost, [data-theme="dark"] .btn-ghost { --btn-fg: var(--color-ink-on-dark-base); }
  :is(.dark-surface .btn-ghost, [data-theme="dark"] .btn-ghost):hover, :is(.dark-surface .btn-ghost, [data-theme="dark"] .btn-ghost)[data-state="hover"] { --btn-fg: var(--color-ink-on-dark-base); background-color: var(--color-fill-dark-subtle); }
  .btn-destructive { background-color: var(--color-red-800); --btn-fg: white; }
  .btn-destructive:hover, .btn-destructive[data-state="hover"] { background-color: var(--color-red-700); }
  .dropdown-trigger-navigation { height: 100%; padding-inline: calc(var(--spacing)*2); }
}
